const DASHBOARD_NEEDLE_REWARD_TIER_COLORS: Record<
  DashboardNeedleRewardTier,
  string
> = {
  common: "34 211 238",
  emerald: "16 185 129",
  epic: "217 70 239",
  rare: "250 204 21",
  uncommon: "52 211 153",
};

const getDashboardStableUnitRoll = (seed: string) => {
  let hash = 2166136261;

  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return (hash >>> 0) / 4294967296;
};

const getDashboardNeedleReward = (progress: number, seed: string) => {
  const chargeRatio = clampDashboardPercent(progress) / 100;
  const weightedPool = DASHBOARD_NEEDLE_REWARD_POOL.map((slot) => {
    const gate =
      chargeRatio >= slot.minCharge || slot.minCharge === 0
        ? 1
        : Math.max(0.02, (chargeRatio / slot.minCharge) * 0.16);
    const weight = Math.max(
      0.02,
      (slot.baseWeight + slot.progressWeight * chargeRatio) * gate,
    );

    return { slot, weight };
  });
  const totalWeight = weightedPool.reduce(
    (total, reward) => total + reward.weight,
    0,
  );
  const roll = getDashboardStableUnitRoll(seed) * totalWeight;
  let cursor = 0;
  const selected =
    weightedPool.find((reward) => {
      cursor += reward.weight;
      return roll <= cursor;
    }) || weightedPool[0];
  const yieldMultiplier = Math.max(1, 1 + Math.floor(chargeRatio * 4));
  const amount =
    selected.slot.tier === "emerald"
      ? Math.max(1, Math.min(2, Math.round(1 + chargeRatio)))
      : selected.slot.baseYield * yieldMultiplier;
  const rareWeight = weightedPool
    .filter((reward) => ["rare", "epic", "emerald"].includes(reward.slot.tier))
    .reduce((total, reward) => total + reward.weight, 0);
  const emeraldWeight =
    weightedPool.find((reward) => reward.slot.tier === "emerald")?.weight || 0;
  const rareChance = (rareWeight / totalWeight) * 100;
  const emeraldChance = (emeraldWeight / totalWeight) * 100;
  const wheelSlots = [
    ...DASHBOARD_NEEDLE_REWARD_POOL,
    ...DASHBOARD_NEEDLE_REWARD_POOL,
  ];

  return {
    amount,
    color: DASHBOARD_NEEDLE_REWARD_TIER_COLORS[selected.slot.tier],
    emeraldChanceLabel:
      emeraldChance < 1
        ? "<1% emerald"
        : `${Math.round(emeraldChance)}% emerald`,
    id: selected.slot.id,
    label: selected.slot.label,
    rareChanceLabel:
      rareChance < 1 ? "<1% rare+" : `${Math.round(rareChance)}% rare+`,
    shortLabel: selected.slot.shortLabel,
    tier: selected.slot.tier,
    unit: selected.slot.unit,
    wheelSlots,
    yieldLabel: `${amount.toLocaleString()} ${
      amount === 1
        ? selected.slot.unit
        : selected.slot.unit === "recovery credit"
          ? "recovery credits"
          : `${selected.slot.unit}s`
    }`,
  };
};

const isDashboardValueComplete = (value: unknown): boolean => {
  if (Array.isArray(value)) return value.some(isDashboardValueComplete);
  if (typeof value === "number") return Number.isFinite(value);
  if (typeof value === "string") return value.trim().length > 0;
  if (typeof value === "boolean") return value;
  if (value && typeof value === "object") {
    return Object.values(value as Record<string, unknown>).some(
      isDashboardValueComplete,
    );
  }

  return false;
};

const getDashboardCompletionFromValues = (values: unknown[]) => {
  if (!values.length) return 0;

  return clampDashboardPercent(
    (values.filter(isDashboardValueComplete).length / values.length) * 100,
  );
};

const readDashboardText = (...values: unknown[]) => {
  const found = values.find(
    (value) => typeof value === "string" && value.trim().length > 0,
  );

  return typeof found === "string" ? found.trim() : "";
};

const readDashboardNumber = (...values: unknown[]) => {
  for (const value of values) {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    if (typeof value !== "string") continue;

    const parsed = Number(value.replace(/,/g, "").trim());
    if (Number.isFinite(parsed) && parsed > 0) return parsed;
  }

  return 0;
};

const formatDashboardCompactCalories = (value: number) => {
  if (value >= 10000) return `${(value / 1000).toFixed(1)}k`;
  return Math.round(value).toLocaleString();
};

const readDashboardLocalRecord = (key: string) => {
  if (typeof window === "undefined") return {};

  try {
    return asRecord(safeJsonParse(window.localStorage.getItem(key)));
  } catch {
    return {};
  }
};

const getDashboardProfileCompletion = (profile: Record<string, unknown>) => {
  const measurements = asRecord(profile.measurements);

  return getDashboardCompletionFromValues([
    profile.displayName,
    profile.birthday,
    profile.height,
    profile.currentWeight,
    measurements.weight,
    profile.waist || measurements.waist,
    profile.primaryGoal,
    profile.secondaryGoal,
    profile.goalMode,
    profile.sessionsPerWeek,
    profile.trainingAge,
    profile.sleepGoal,
    profile.occupation,
    profile.phone,
    profile.email,
  ]);
};

const getDashboardGoalsCompletion = (goals: Record<string, unknown>) =>
  getDashboardCompletionFromValues([
    goals.planDirections,
    goals.primaryGoal,
    goals.secondaryGoal,
    goals.goalMode,
    goals.goalDeadline,
    goals.goalMilestones,
    goals.goalPriorityRanking,
    goals.goalWeight || goals.currentWeight,
    goals.targetWeeklySessions,
    goals.targetWeeklySets,
    goals.targetProtein,
    goals.targetSteps || goals.stepsGoal,
    goals.targetSleep,
    goals.waterGoal,
    goals.benchmarkGoal,
    goals.motivationFocus,
    goals.planDirectionNotes,
  ]);

const getDashboardGoalFocus = (
  profile: Record<string, unknown>,
  goals: Record<string, unknown>,
) =>
  readDashboardText(
    Array.isArray(goals.planDirections) ? goals.planDirections[0] : "",
    goals.primaryGoal,
    goals.goalMode,
    profile.primaryGoal,
    profile.goalMode,
  );

const readDashboardFoundationProgress = (): DashboardFoundationProgress => {
  if (typeof window === "undefined") {
    return {
      goalFocus: "",
      goalsCompletion: 0,
      goalsVisited: false,
      profileCompletion: 0,
      profileVisited: false,
    };
  }

  const profile = readDashboardLocalRecord(SOUND_FITNESS_PROFILE_STORAGE_KEY);
  const goals = readDashboardLocalRecord(DASHBOARD_GOALS_STORAGE_KEY);

  return {
    goalFocus: getDashboardGoalFocus(profile, goals),
    goalsCompletion: getDashboardGoalsCompletion(goals),
    goalsVisited:
      window.localStorage.getItem(DASHBOARD_GOALS_VISITED_KEY) === "true",
    profileCompletion: getDashboardProfileCompletion(profile),
    profileVisited:
      window.localStorage.getItem(DASHBOARD_PROFILE_VISITED_KEY) === "true",
  };
};

const readDashboardProfileIconUrl = (
  fallback = DASHBOARD_PROFILE_ICON_FALLBACK,
) => {
  if (typeof window === "undefined") return fallback;

  const profile = readDashboardLocalRecord(SOUND_FITNESS_PROFILE_STORAGE_KEY);
  return (
    readDashboardText(
      profile.profileImage,
      profile.avatarUrl,
      profile.avatar_url,
      fallback,
    ) || DASHBOARD_PROFILE_ICON_FALLBACK
  );
};

const getDashboardPulseIndicatorTone = (
  percent: number,
): DashboardPulseIndicatorTone => {
  if (percent >= 80) {
    return {
      dotActive: "bg-emerald-300 shadow-[0_0_12px_rgba(52,211,153,0.72)]",
      dotInactive: "bg-emerald-300/80 shadow-[0_0_10px_rgba(52,211,153,0.46)]",
      motion: "water",
      outerActive: "border-emerald-100/42 ring-1 ring-emerald-200/38",
      outerInactive: "border-emerald-300/22 ring-1 ring-emerald-300/18",
      style: {
        "--profile-indicator-glow": "rgba(52,211,153,0.92)",
        "--profile-indicator-glow-dim": "rgba(52,211,153,0.46)",
        "--profile-indicator-glow-soft": "rgba(16,185,129,0.34)",
      } as DashboardPulseIndicatorStyle,
    };
  }

  if (percent >= 50) {
    return {
      dotActive: "bg-cyan-200 shadow-[0_0_12px_rgba(103,232,249,0.72)]",
      dotInactive: "bg-cyan-300/80 shadow-[0_0_10px_rgba(34,211,238,0.46)]",
      motion: "pulse",
      outerActive: "border-cyan-100/42 ring-1 ring-cyan-200/38",
      outerInactive: "border-cyan-300/22 ring-1 ring-cyan-300/18",
      style: {
        "--profile-indicator-glow": "rgba(103,232,249,0.92)",
        "--profile-indicator-glow-dim": "rgba(34,211,238,0.46)",
        "--profile-indicator-glow-soft": "rgba(34,211,238,0.34)",
      } as DashboardPulseIndicatorStyle,
    };
  }

  if (percent >= 25) {
    return {
      dotActive: "bg-amber-300 shadow-[0_0_12px_rgba(251,191,36,0.72)]",
      dotInactive: "bg-amber-300/80 shadow-[0_0_10px_rgba(251,191,36,0.46)]",
      motion: "pulse",
      outerActive: "border-amber-100/42 ring-1 ring-amber-200/38",
      outerInactive: "border-amber-300/22 ring-1 ring-amber-300/18",
      style: {
        "--profile-indicator-glow": "rgba(251,191,36,0.92)",
        "--profile-indicator-glow-dim": "rgba(251,191,36,0.46)",
        "--profile-indicator-glow-soft": "rgba(245,158,11,0.34)",
      } as DashboardPulseIndicatorStyle,
    };
  }

  return {
    dotActive: "bg-rose-300 shadow-[0_0_12px_rgba(251,113,133,0.72)]",
    dotInactive: "bg-rose-300/80 shadow-[0_0_10px_rgba(251,113,133,0.46)]",
    motion: "pulse",
    outerActive: "border-rose-100/42 ring-1 ring-rose-200/38",
    outerInactive: "border-rose-300/22 ring-1 ring-rose-300/18",
    style: {
      "--profile-indicator-glow": "rgba(251,113,133,0.92)",
      "--profile-indicator-glow-dim": "rgba(251,113,133,0.46)",
      "--profile-indicator-glow-soft": "rgba(244,63,94,0.34)",
    } as DashboardPulseIndicatorStyle,
  };
};

